package coralnpu

import chisel3._
import chisel3.util._

/** BlackBox referencing the external RstSync.sv Verilog module.
  *
  * Two-FF reset synchronizer.  The reset de-assertion (d going high) is
  * synchronised to the rising edge of clk; assertion (d going low) is
  * propagated asynchronously.
  *
  * Port naming matches the Verilog module exactly so that Chisel emits the
  * correct instance connections without any renaming.
  */
class RstSync extends BlackBox {
  val io = IO(new Bundle {
    val clk = Input(Clock())
    val d   = Input(Bool())
    val q   = Output(Bool())
  })
}

