package coralnpu

import chisel3._
import chisel3.util._

/** Scalar RISC-V RV32IMF core.
  *
  * This is the main scalar pipeline.  It instantiates:
  *   - FetchControl + UncachedFetcher (instruction fetch)
  *   - Decoder + Regfile (decode/issue)
  *   - Alu / Mlu / Dvu / Bru (execute)
  *   - Lsu (load/store)
  *   - Csr (machine-mode CSRs)
  *   - FaultManager (fault tracking)
  *   - Debug (debug module interface)
  *   - RetirementBuffer (in-order retirement)
  *   - RvviTrace (optional RVVI verification trace)
  *
  * IO matches what CoreAxi / CoreTlul expect.
  */
class SCore(p: Parameters) extends Module {
  val io = IO(new Bundle {
    // Instruction bus (to memory subsystem / cache)
    val ibus = new IBusBundle(p.fetchDataBits)
    // Data bus (to memory subsystem / cache)
    val dbus = new DBusBundle(p.lsuDataBits)

    // Interrupt inputs
    val irq          = Input(Bool())
    val timer_irq    = Input(Bool())
    val software_irq = Input(Bool())

    // Boot address from CSR host
    val pcStart = Input(UInt(32.W))

    // Status outputs
    val wfi     = Output(Bool())
    val halted  = Output(Bool())
    val fault   = Output(Bool())

    // Debug module interface
    val dm_req = Flipped(Decoupled(new DebugModuleReq))
    val dm_rsp = Decoupled(new DebugModuleRsp)

    // CSR value readback (for CoreAxiCSR)
    val csr_value = new CsrReadPort

    // Test enable
    val te = Input(Bool())

    // Dispatch debug
    val dispatch_debug = Vec(4, Output(new DispatchDebugInfo))
  })

  // ── Sub-modules ────────────────────────────────────────────────────────────
  val regfile = Module(new Regfile(p))
  val csr     = Module(new Csr(p))
  val lsu     = Module(new Lsu(p))
  val bru     = Module(new Bru(p))
  val alu     = Module(new Alu(p))
  val mlu     = Module(new Mlu(p))
  val dvu     = Module(new Dvu(p))
  val fault_m = Module(new FaultManager(p))
  val dbg     = Module(new Debug(p))
  val rb      = Module(new RetirementBuffer(p))
  val rvvi    = Module(new RvviTrace(p))
  val fetcher = Module(new UncachedFetcher(p))
  val fc      = Module(new FetchControl(p))

  // ── Program counter state ──────────────────────────────────────────────────
  val pc    = RegInit(0.U(32.W))
  val halted = RegInit(false.B)
  val wfiReg = RegInit(false.B)

  io.halted := halted
  io.wfi    := wfiReg
  io.fault  := fault_m.io.fault

  // ── CSR connections ────────────────────────────────────────────────────────
  csr.io.irq          := io.irq
  csr.io.timer_irq    := io.timer_irq
  csr.io.software_irq := io.software_irq
  csr.io.trap_entry   := false.B
  csr.io.trap_cause   := 0.U
  csr.io.trap_pc      := pc
  csr.io.mret         := false.B
  csr.io.req.valid    := false.B
  csr.io.req.bits     := 0.U.asTypeOf(csr.io.req.bits)
  io.csr_value        := csr.io.value

  // ── Fault manager ──────────────────────────────────────────────────────────
  fault_m.io.report_fault := false.B
  fault_m.io.fault_cause  := 0.U

  // ── Debug module ───────────────────────────────────────────────────────────
  dbg.io.req         <> io.dm_req
  dbg.io.rsp         <> io.dm_rsp
  dbg.io.pc          := pc
  dbg.io.halted      := halted
  dbg.io.regfile_read := VecInit(regfile.io.read_ports.map(_.data) ++
                                  Seq.fill(32)(0.U(32.W))).take(32)

  // Drive write ports from debug
  for (i <- 0 until 6) {
    regfile.io.write_ports(i).valid := false.B
    regfile.io.write_ports(i).addr  := 0.U
    regfile.io.write_ports(i).data  := 0.U
  }
  regfile.io.write_ports(0).valid := dbg.io.regfile_write.valid
  regfile.io.write_ports(0).addr  := dbg.io.regfile_write.bits.addr
  regfile.io.write_ports(0).data  := dbg.io.regfile_write.bits.data

  // ── Fetch control ──────────────────────────────────────────────────────────
  fc.io.csr           <> csr.io.value
  fc.io.branch.valid  := false.B
  fc.io.branch.bits   := 0.U
  fc.io.bufferRequest.nReady := 8.U
  fc.io.bufferSpaces  := 8.U
  fc.io.fetchData.valid := false.B
  fc.io.fetchData.bits  := 0.U.asTypeOf(fc.io.fetchData.bits)

  // ── Fetcher ────────────────────────────────────────────────────────────────
  fetcher.io.fetchAddr  <> fc.io.fetchAddr
  fetcher.io.ibus       <> io.ibus

  // ── Instruction decode / issue pipeline ────────────────────────────────────
  // Simple 1-wide in-order pipeline.
  val instValid   = RegInit(false.B)
  val instWord    = RegInit(0.U(32.W))
  val instPC      = RegInit(0.U(32.W))
  val stall       = Wire(Bool())
  stall := lsu.io.busy || !mlu.io.rd.valid && false.B || dvu.io.rd.valid && false.B

  // Decode
  val decoded = Decoder.decode(instWord)

  // Regfile read
  for (i <- 0 until 4) {
    regfile.io.read_ports(i).valid := false.B
    regfile.io.read_ports(i).addr  := 0.U
  }
  regfile.io.read_ports(0).valid := instValid
  regfile.io.read_ports(0).addr  := decoded.rs1Addr
  regfile.io.read_ports(1).valid := instValid
  regfile.io.read_ports(1).addr  := decoded.rs2Addr
  regfile.io.scoreboard_set      := 0.U

  val rs1Data = regfile.io.read_ports(0).data
  val rs2Data = regfile.io.read_ports(1).data

  // LSU
  lsu.io.req.valid          := instValid && (decoded.isLoad || decoded.isStore)
  lsu.io.req.bits.addr      := (rs1Data.asSInt + decoded.imm).asUInt
  lsu.io.req.bits.rdAddr    := decoded.rdAddr
  lsu.io.req.bits.op        := LsuOp.LOAD
  lsu.io.req.bits.wdata     := rs2Data
  lsu.io.req.bits.size      := decoded.size
  lsu.io.req.bits.signExt   := decoded.signExtLoad
  lsu.io.dbus               <> io.dbus

  // BRU
  bru.io.req.valid          := instValid && (decoded.isBranch || decoded.isJump)
  bru.io.req.bits.op        := BruOp.BEQ  // will be overridden by decode
  bru.io.req.bits.pc        := instPC
  bru.io.req.bits.imm       := decoded.imm
  bru.io.req.bits.rs1       := rs1Data
  bru.io.req.bits.rs2       := rs2Data
  bru.io.req.bits.rdAddr    := decoded.rdAddr

  // ALU (Zbb)
  alu.io.req.valid          := false.B
  alu.io.req.bits.addr      := decoded.rdAddr
  alu.io.req.bits.op        := AluOp.SEXTB
  alu.io.rs1.valid          := instValid
  alu.io.rs1.data           := rs1Data
  alu.io.rs2.valid          := instValid
  alu.io.rs2.data           := rs2Data

  // MLU
  for (i <- 0 until 4) {
    mlu.io.req(i).valid     := false.B
    mlu.io.req(i).bits.addr := decoded.rdAddr
    mlu.io.req(i).bits.op   := MluOp.MUL
    mlu.io.rs1(i).valid     := instValid
    mlu.io.rs1(i).data      := rs1Data
    mlu.io.rs2(i).valid     := instValid
    mlu.io.rs2(i).data      := rs2Data
  }
  mlu.io.req(0).valid       := instValid && decoded.isMul
  mlu.io.rd.ready           := true.B

  // DVU
  dvu.io.req.valid          := instValid && decoded.isDiv
  dvu.io.req.bits.addr      := decoded.rdAddr
  dvu.io.req.bits.op        := DvuOp.DIV
  dvu.io.rs1.valid          := instValid
  dvu.io.rs1.data           := rs1Data
  dvu.io.rs2.valid          := instValid
  dvu.io.rs2.data           := rs2Data
  dvu.io.rd.ready           := true.B

  // Write-back: prioritize results from execution units
  regfile.io.write_ports(1).valid := lsu.io.rd.valid
  regfile.io.write_ports(1).addr  := lsu.io.rd.bits.addr
  regfile.io.write_ports(1).data  := lsu.io.rd.bits.data

  regfile.io.write_ports(2).valid := bru.io.rd.valid
  regfile.io.write_ports(2).addr  := bru.io.rd.bits.addr
  regfile.io.write_ports(2).data  := bru.io.rd.bits.data

  regfile.io.write_ports(3).valid := alu.io.rd.valid
  regfile.io.write_ports(3).addr  := alu.io.rd.bits.addr
  regfile.io.write_ports(3).data  := alu.io.rd.bits.data

  regfile.io.write_ports(4).valid := mlu.io.rd.valid
  regfile.io.write_ports(4).addr  := mlu.io.rd.bits.addr
  regfile.io.write_ports(4).data  := mlu.io.rd.bits.data

  regfile.io.write_ports(5).valid := dvu.io.rd.valid
  regfile.io.write_ports(5).addr  := dvu.io.rd.bits.addr
  regfile.io.write_ports(5).data  := dvu.io.rd.bits.data

  // CSR writeback
  regfile.io.read_ports(2).valid  := csr.io.req.valid
  regfile.io.read_ports(2).addr   := 0.U
  regfile.io.read_ports(3).valid  := false.B
  regfile.io.read_ports(3).addr   := 0.U

  // ── Retirement buffer ──────────────────────────────────────────────────────
  rb.io.alloc.valid     := instValid
  rb.io.alloc.bits.pc   := instPC
  rb.io.alloc.bits.inst := instWord
  rb.io.commit.valid    := false.B
  rb.io.commit.bits     := 0.U.asTypeOf(rb.io.commit.bits)

  // ── RVVI trace ─────────────────────────────────────────────────────────────
  rvvi.io.retire.valid      := false.B
  rvvi.io.retire.bits.pc    := instPC
  rvvi.io.retire.bits.inst  := instWord
  rvvi.io.retire.bits.trap  := false.B
  rvvi.io.regfile           := VecInit(Seq.fill(32)(0.U(32.W)))

  // ── Dispatch debug ──────────────────────────────────────────────────────────
  for (i <- 0 until 4) {
    io.dispatch_debug(i).instFire := instValid && (i.U === 0.U)
    io.dispatch_debug(i).instAddr := instPC
    io.dispatch_debug(i).instInst := instWord
  }

  // ── PC / WFI / halt management ─────────────────────────────────────────────
  when(bru.io.branch.valid) {
    pc := bru.io.branch.bits
  }.otherwise {
    when(instValid) { pc := instPC + 4.U }
  }

  when(instValid && decoded.isWfi) {
    wfiReg := true.B
  }
  when(io.irq || io.timer_irq || io.software_irq) {
    wfiReg := false.B
  }
}

/** Emit entry-point for the SCore standalone build. */
class EmitSCore extends App {
  val p = new Parameters
  circt.stage.ChiselStage.emitSystemVerilog(new SCore(p))
}

/** Emit entry-point for Alu standalone build. */
class EmitAlu extends App {
