import chisel3.util._
import bus._

/** Core — integrates SCore with the memory subsystem.
  *
  * Provides:
  *   - ITCM and DTCM (tightly-coupled memories)
  *   - L1ICache and L1DCache (pass-through stubs)
  *   - Optional AXI master port for external memory access
  *   - AXI slave back-door port for firmware loading and CSR access
  *   - FabricMux + FabricArbiter (internal address-decode and arbitration)
  *
  * Memory map (CPU-side byte addresses):
  * {{{
  *   0x00000000 .. itcmSizeBytes-1      → ITCM
  *   0x00010000 .. 0x10000+dtcm-1       → DTCM
  *   0x20000000 ..                      → External (AXI master)
  * }}}
  */
class Core(p: Parameters) extends Module {

  // ── Address constants ──────────────────────────────────────────────────────
  val ITCM_BASE: Long = 0x00000000L
  val DTCM_BASE: Long = 0x00010000L
  val EXT_BASE:  Long = 0x20000000L

  // ── Ports ──────────────────────────────────────────────────────────────────
  val io = IO(new Bundle {
    // ---- AXI slave (host → core) -------------------------------------------
    val axi_slave = Option.when(p.useAxi || p.useTlul)(
      Flipped(new AxiBundle(128, p.addrBits, p.axiIdBits))
    )

    // ---- AXI master (core → external memory) --------------------------------
    val axi_master = Option.when(p.useAxi)(
      new AxiBundle(p.lsuDataBits, p.addrBits, p.axi2IdBits)
    )

    // ---- Interrupts ---------------------------------------------------------
    val irq          = Input(Bool())
    val timer_irq    = Input(Bool())
    val software_irq = Input(Bool())

    // ---- Boot address override ----------------------------------------------
    val pcStart = Input(UInt(32.W))

    // ---- Status -------------------------------------------------------------
    val wfi     = Output(Bool())
    val halted  = Output(Bool())
    val fault   = Output(Bool())

    // ---- Debug module -------------------------------------------------------
    val dm_req = Flipped(Decoupled(new DebugModuleReq))
    val dm_rsp = Decoupled(new DebugModuleRsp)

    // ---- Test enable --------------------------------------------------------
    val te = Input(Bool())
  })

  // ── SCore ─────────────────────────────────────────────────────────────────
  val score = Module(new SCore(p))
  score.io.irq          := io.irq
  score.io.timer_irq    := io.timer_irq
  score.io.software_irq := io.software_irq
  score.io.pcStart      := io.pcStart
  score.io.te           := io.te
  io.wfi                := score.io.wfi
  io.halted             := score.io.halted
  io.fault              := score.io.fault
  score.io.dm_req       <> io.dm_req
  score.io.dm_rsp       <> io.dm_rsp

  // ── Memories ───────────────────────────────────────────────────────────────
  val itcm = Module(new TCM(p.itcmSizeBytes, ITCM_BASE))
  val dtcm = Module(new TCM(p.dtcmSizeBytes, DTCM_BASE))

  // Back-door defaults (overridden by AxiSlave when present)
  itcm.io.backdoor.en    := false.B
  itcm.io.backdoor.we    := false.B
  itcm.io.backdoor.addr  := 0.U
  itcm.io.backdoor.wdata := 0.U
  itcm.io.backdoor.wmask := 0.U
  dtcm.io.backdoor.en    := false.B
  dtcm.io.backdoor.we    := false.B
  dtcm.io.backdoor.addr  := 0.U
  dtcm.io.backdoor.wdata := 0.U
  dtcm.io.backdoor.wmask := 0.U

  // ── L1 caches (pass-through) ───────────────────────────────────────────────
  val l1i = Module(new L1ICache(p))
  val l1d = Module(new L1DCache(p))

  l1i.io.cpu <> score.io.ibus
  l1d.io.cpu <> score.io.dbus

  // ── Instruction bus → ITCM ────────────────────────────────────────────────
  // ITCM CPU port: instruction fetch (read-only from CPU)
  val ibusAddr    = l1i.io.mem.addr
  val inITCMIBus  = ibusAddr < p.itcmSizeBytes.U

  itcm.io.cpu.en    := l1i.io.mem.valid && inITCMIBus
  itcm.io.cpu.we    := false.B
  itcm.io.cpu.addr  := ibusAddr(log2Ceil(p.itcmSizeBytes) - 1, 0)
  itcm.io.cpu.wdata := 0.U
  itcm.io.cpu.wmask := 0.U
  l1i.io.mem.ready  := true.B  // 1-cycle latency; data valid next cycle
  l1i.io.mem.rdata  := itcm.io.cpu.rdata

  // ── Data bus → fabric ──────────────────────────────────────────────────────
  // FabricMux decodes data bus accesses to ITCM / DTCM / external
  val memoryRegions = Seq(
    new MemoryRegion(ITCM_BASE, p.itcmSizeBytes, MemoryRegionType.IMEM),
    new MemoryRegion(DTCM_BASE, p.dtcmSizeBytes, MemoryRegionType.DMEM),
    new MemoryRegion(EXT_BASE,  0x10000000L,      MemoryRegionType.Peripheral),
  )
  val fabricMux = Module(new FabricMux(p, memoryRegions))

  // Convert DBusBundle → FabricPort (source)
  val dbusAddr  = l1d.io.mem.addr
  val dbusWrite = l1d.io.mem.write

  fabricMux.io.source.readDataAddr.valid  := l1d.io.mem.valid && !dbusWrite
  fabricMux.io.source.readDataAddr.bits   := dbusAddr
  fabricMux.io.source.writeDataAddr.valid := l1d.io.mem.valid && dbusWrite
  fabricMux.io.source.writeDataAddr.bits  := dbusAddr
  fabricMux.io.source.writeDataBits       := l1d.io.mem.wdata
  fabricMux.io.source.writeDataStrb       := l1d.io.mem.wmask

  // Default periBusy = false; overridden by AXI master bridge below
  for (i <- 0 until memoryRegions.length) {
    fabricMux.io.periBusy(i) := false.B
  }

  l1d.io.mem.ready := fabricMux.io.source.readDataAddr.ready ||
                      fabricMux.io.source.writeDataAddr.ready
  l1d.io.mem.rdata := fabricMux.io.source.readData.bits

  // ── ITCM data bus port ─────────────────────────────────────────────────────
  val itcmDataPort = fabricMux.io.ports(0)
  val itcmWrite   = itcmDataPort.writeDataAddr.valid

  // DTCM overrides itcm cpu port when data bus addresses ITCM
  // (itcm.io.cpu is used by ibus; share via priority — ibus wins)
  // For simplicity, ITCM data access goes through the same TCM cpu port
  // when ibus is idle.
  val itcmDataEn = itcmDataPort.readDataAddr.valid || itcmDataPort.writeDataAddr.valid
  // Note: true dual-ported TCM would be needed for simultaneous ibus+dbus;
  // for this design ibus has priority and dbus stalls.
  when(itcmDataEn && !itcm.io.cpu.en) {
    itcm.io.cpu.en    := itcmDataEn
    itcm.io.cpu.we    := itcmWrite
    itcm.io.cpu.addr  := Mux(itcmWrite,
      itcmDataPort.writeDataAddr.bits(log2Ceil(p.itcmSizeBytes) - 1, 0),
      itcmDataPort.readDataAddr.bits(log2Ceil(p.itcmSizeBytes) - 1, 0))
    itcm.io.cpu.wdata := itcmDataPort.writeDataBits
    itcm.io.cpu.wmask := itcmDataPort.writeDataStrb
  }

  itcmDataPort.readDataAddr.ready  := true.B
  itcmDataPort.writeDataAddr.ready := true.B
  itcmDataPort.readData.valid      := RegNext(itcmDataPort.readDataAddr.valid)
  itcmDataPort.readData.bits       := itcm.io.cpu.rdata

  // ── DTCM data bus port ──────────────────────────────────────────────────────
  val dtcmDataPort = fabricMux.io.ports(1)
  val dtcmWrite    = dtcmDataPort.writeDataAddr.valid

  dtcm.io.cpu.en    := dtcmDataPort.readDataAddr.valid || dtcmDataPort.writeDataAddr.valid
  dtcm.io.cpu.we    := dtcmWrite
  dtcm.io.cpu.addr  := Mux(dtcmWrite,
    dtcmDataPort.writeDataAddr.bits(log2Ceil(p.dtcmSizeBytes) - 1, 0),
    dtcmDataPort.readDataAddr.bits(log2Ceil(p.dtcmSizeBytes) - 1, 0))
  dtcm.io.cpu.wdata := dtcmDataPort.writeDataBits
  dtcm.io.cpu.wmask := dtcmDataPort.writeDataStrb

  dtcmDataPort.readDataAddr.ready  := true.B
  dtcmDataPort.writeDataAddr.ready := true.B
  dtcmDataPort.readData.valid      := RegNext(dtcmDataPort.readDataAddr.valid)
  dtcmDataPort.readData.bits       := dtcm.io.cpu.rdata

  // ── External AXI master port ───────────────────────────────────────────────
  val extDataPort = fabricMux.io.ports(2)

  if (p.useAxi) {
    val dbus2axi = Module(new DBus2AxiV2(p))

    // Convert FabricPort → DBusBundle for DBus2AxiV2
    dbus2axi.io.dbus.valid  := extDataPort.readDataAddr.valid || extDataPort.writeDataAddr.valid
    dbus2axi.io.dbus.addr   := Mux(extDataPort.writeDataAddr.valid,
      extDataPort.writeDataAddr.bits + EXT_BASE.U,
      extDataPort.readDataAddr.bits + EXT_BASE.U)
    dbus2axi.io.dbus.write  := extDataPort.writeDataAddr.valid
    dbus2axi.io.dbus.wdata  := extDataPort.writeDataBits
    dbus2axi.io.dbus.wmask  := extDataPort.writeDataStrb
    dbus2axi.io.dbus.size   := (p.lsuDataBits / 8).U
    dbus2axi.io.dbus.rdata  <> DontCare

    extDataPort.readDataAddr.ready  := dbus2axi.io.dbus.ready && !extDataPort.writeDataAddr.valid
    extDataPort.writeDataAddr.ready := dbus2axi.io.dbus.ready && extDataPort.writeDataAddr.valid
    extDataPort.readData.valid      := false.B
    extDataPort.readData.bits       := dbus2axi.io.dbus.rdata
    fabricMux.io.periBusy(2)        := !dbus2axi.io.dbus.ready &&
                                       (extDataPort.readDataAddr.valid || extDataPort.writeDataAddr.valid)

    dbus2axi.io.axi <> io.axi_master.get
  } else {
    extDataPort.readDataAddr.ready  := false.B
    extDataPort.writeDataAddr.ready := false.B
    extDataPort.readData.valid      := false.B
    extDataPort.readData.bits       := 0.U
    // Tie off axi_master if it somehow exists without useAxi
  }

  // ── AXI slave (host back-door) ─────────────────────────────────────────────
  if (p.useAxi || p.useTlul) {
    val axiSlv = Module(new AxiSlave(p))
    val csrMod = Module(new CoreAxiCSR(p))

    axiSlv.io.axi      <> io.axi_slave.get
    axiSlv.io.csrAxi   <> csrMod.io.axi

    // ITCM back-door
    itcm.io.backdoor.en    := axiSlv.io.itcm.en
    itcm.io.backdoor.we    := axiSlv.io.itcm.we
    itcm.io.backdoor.addr  := axiSlv.io.itcm.addr ## 0.U(log2Ceil(16).W)  // word → byte addr
    itcm.io.backdoor.wdata := axiSlv.io.itcm.wdata
    itcm.io.backdoor.wmask := axiSlv.io.itcm.wmask
    axiSlv.io.itcm.rdata   := itcm.io.backdoor.rdata

    // DTCM back-door
    dtcm.io.backdoor.en    := axiSlv.io.dtcm.en
    dtcm.io.backdoor.we    := axiSlv.io.dtcm.we
    dtcm.io.backdoor.addr  := axiSlv.io.dtcm.addr ## 0.U(log2Ceil(16).W)
    dtcm.io.backdoor.wdata := axiSlv.io.dtcm.wdata
    dtcm.io.backdoor.wmask := axiSlv.io.dtcm.wmask
    axiSlv.io.dtcm.rdata   := dtcm.io.backdoor.rdata

    // CSR → SCore boot address
    score.io.pcStart := Mux(io.pcStart =/= 0.U, io.pcStart, csrMod.io.pcStart)

    // CSR connections
    csrMod.io.internal     := false.B
    csrMod.io.halted       := score.io.halted
    csrMod.io.fault        := score.io.fault
    csrMod.io.coralnpu_csr := score.io.csr_value
  }
}

