/** CoreAxi — top-level RawModule with explicit AXI clock and reset.
  *
  * This is the module emitted as `CoreMiniAxi.sv` (or similar) and instantiated
  * by the testbench via the `core_mini_axi_interface.py` driver.
  *
  * The clock and reset are explicit ports (`aclk`, `aresetn`) rather than
  * being implicit Chisel module ports.  `aresetn` follows the AXI convention
  * (active-low reset): when aresetn=0, the core is held in reset; when
  * aresetn=1, the core runs.  This is converted to Chisel's active-high reset
  * internally via `!aresetn`.
  *
  * A `ClockGate` and `RstSync` module provide clock gating and reset
  * synchronisation controlled by the `CoreAxiCSR` registers.
  */
class CoreAxi(p: Parameters, moduleName: String = "CoreMiniAxi")
    extends RawModule {

  // ── Explicit clock / reset ─────────────────────────────────────────────────
  val io_aclk    = IO(Input(Clock()))
  val io_aresetn = IO(Input(Bool()))   // active-low

  // ── AXI slave (128-bit, host → core) ──────────────────────────────────────
  val io_axi_slave = IO(Flipped(new AxiBundle(128, p.addrBits, p.axiIdBits)))

  // ── AXI master (lsuDataBits-wide, core → external memory) ─────────────────
  val io_axi_master = IO(new AxiBundle(p.lsuDataBits, p.addrBits, p.axi2IdBits))

  // ── Interrupts ─────────────────────────────────────────────────────────────
  val io_irq          = IO(Input(Bool()))
  val io_timer_irq    = IO(Input(Bool()))
  val io_software_irq = IO(Input(Bool()))

  // ── Status ─────────────────────────────────────────────────────────────────
  val io_wfi    = IO(Output(Bool()))
  val io_halted = IO(Output(Bool()))
  val io_fault  = IO(Output(Bool()))

  // ── Boot address override ──────────────────────────────────────────────────
  val io_boot_addr = IO(Input(UInt(32.W)))

  // ── Test enable ────────────────────────────────────────────────────────────
  val io_te = IO(Input(Bool()))

  // ── Debug module ───────────────────────────────────────────────────────────
  val io_dm_req = IO(Flipped(Decoupled(new DebugModuleReq)))
  val io_dm_rsp = IO(Decoupled(new DebugModuleRsp))

  // ── Clock gate + reset synchroniser ───────────────────────────────────────
  val cg      = Module(new ClockGate)
  val rstSync = Module(new RstSync)

  // The CSR controls cg and reset; we need to instantiate them inside the
  // gated-clock domain.  For the top-level we use a simple approach:
  // ClockGate.enable is driven combinationally from an output of Core.
  // The ClockGate defaults to pass-through (enable=true) until CSR overrides.

  // Reset synchroniser: synchronises aresetn (active-low) to aclk.
  rstSync.io.clk := io_aclk
  rstSync.io.d   := io_aresetn  // 0 = reset asserted
  val syncRstN = rstSync.io.q   // synchronised active-low reset

  // Gated clock (enable driven inside the clocked domain — see below)
  cg.io.clk_i  := io_aclk
  cg.io.te     := io_te
  // enable will be driven once we have the CSR module

  // ── Core instantiation inside gated clock domain ───────────────────────────
  withClockAndReset(cg.io.clk_o, !syncRstN) {
    val core = Module(new Core(p))

    // AXI slave
    core.io.axi_slave.foreach { slv => slv <> io_axi_slave }

    // AXI master
    core.io.axi_master.foreach { mst => mst <> io_axi_master }

    // Interrupts and control
    core.io.irq          := io_irq
    core.io.timer_irq    := io_timer_irq
    core.io.software_irq := io_software_irq
    core.io.pcStart      := io_boot_addr
    core.io.te           := io_te

    // Debug
    core.io.dm_req       <> io_dm_req
    core.io.dm_rsp       <> io_dm_rsp

    // Status
    io_wfi    := core.io.wfi
    io_halted := core.io.halted
    io_fault  := core.io.fault

    // Drive clock gate enable: enabled (not gated) by default
    // The Core's CSR will drive this; for now use a simple register
    cg.io.enable := true.B
  }
}

/** CoreTlulAxi variant (alias for AXI top-level). */
class CoreMiniAxi(p: Parameters) extends CoreAxi(p, "CoreMiniAxi")

/** Emit entry-point for EmitCore.
  *
  * Reads command-line flags and emits the appropriate top-level module.
  * Supported flags:
  *   --moduleName=<name>         Module name (default "CoreMini")
  *   --useAxi                    Emit CoreAxi top-level
  *   --useTlul                   Emit CoreTlul top-level
  *   --enableFloat=<True|False>
  *   --enableRvv=<True|False>
  *   --enableFetchL0=<True|False>
  *   --enableVerification=<True|False>
  *   --fetchDataBits=<N>
  *   --lsuDataBits=<N>
  *   --itcmSizeKBytes=<N>
  *   --dtcmSizeKBytes=<N>
  *   --outputDir=<path>
  */
class EmitCore extends App {
  val p = new Parameters

  // ── Argument parsing ─────────────────────────────────────────────────────
  var moduleName  = "CoreMini"
  var outputDir   = "generated"

  args.foreach { arg =>
    val kv = arg.stripPrefix("--").split("=", 2)
    if (kv.length == 2) {
      val (key, value) = (kv(0), kv(1))
      key match {
        case "moduleName"         => moduleName  = value
        case "outputDir"          => outputDir   = value
        case "enableFloat"        => p.enableFloat        = value.toLowerCase != "false"
        case "enableRvv"          => p.enableRvv          = value.toLowerCase != "false"
        case "enableFetchL0"      => p.enableFetchL0      = value.toLowerCase != "false"
        case "enableVerification" => p.enableVerification = value.toLowerCase != "false"
        case "fetchDataBits"      => p.fetchDataBits      = value.toInt
        case "lsuDataBits"        => p.lsuDataBits        = value.toInt
        case "itcmSizeKBytes"     => p.itcmSizeBytes      = MemorySize.kbytes(value.toInt)
        case "dtcmSizeKBytes"     => p.dtcmSizeBytes      = MemorySize.kbytes(value.toInt)
        case "useAxi"             => p.useAxi             = true
        case "useTlul"            => p.useTlul            = true
        case _                    => // ignore unknown flags
      }
    } else if (kv.length == 1) {
      kv(0) match {
        case "useAxi"  => p.useAxi  = true
        case "useTlul" => p.useTlul = true
        case _         => // ignore
      }
    }
  }

  // ── Emit SystemVerilog ─────────────────────────────────────────────────────
  val targetName = moduleName  // used for module name in emitted SV

  val annotations = Seq(
    new chisel3.stage.ChiselGeneratorAnnotation(() =>
      if (p.useAxi) new CoreAxi(p, targetName)
      else if (p.useTlul) new CoreTlul(p, targetName)
      else new CoreAxi(p, targetName)  // default to AXI
    )
  )

  // Use circt for emission
  import circt.stage.{ChiselStage, FirtoolOption}
  val sv = ChiselStage.emitSystemVerilogFile(
    if (p.useAxi) new CoreAxi(p, targetName)
    else if (p.useTlul) new CoreTlul(p, targetName)
    else new CoreAxi(p, targetName),
    Array("--target-dir", outputDir),
    firtoolOpts = Array("-disable-all-randomization", "-strip-debug-info")
  )

  // ── Emit parameters header ─────────────────────────────────────────────────
  val headerName = s"V${targetName}Axi_parameters.h"
  val header = s"""// Auto-generated by EmitCore — do not edit.
#ifndef V${targetName}_PARAMETERS_H_
#define V${targetName}_PARAMETERS_H_

#define KP_lsuDataBits         ${p.lsuDataBits}
#define KP_fetchDataBits       ${p.fetchDataBits}
#define KP_addrBits            ${p.addrBits}
#define KP_axi2AddrBits        ${p.axi2AddrBits}
#define KP_axi2IdBits          ${p.axi2IdBits}
#define KP_axiIdBits           ${p.axiIdBits}
#define KP_enableFloat         ${p.enableFloat}
#define KP_enableRvv           ${p.enableRvv}
#define KP_rvvVlen             128
#define KP_retirementBufferSize    ${RetirementBufferConfig.size}
#define KP_retirementBufferIdxWidth ${RetirementBufferConfig.idxWidth}

#endif  // V${targetName}_PARAMETERS_H_
"""
  val hdrPath = s"$outputDir/$headerName"
  val fw = new java.io.FileWriter(hdrPath)
  fw.write(header)
  fw.close()
}

